644: static int init_journal(struct gfs2_sbd *sdp, int undo)
645: {
646: 	struct inode *master = d_inode(sdp->sd_master_dir);
647: 	struct gfs2_holder ji_gh;
648: 	struct gfs2_inode *ip;
649: 	int jindex = 1;
650: 	int error = 0;
651: 
652: 	if (undo) {
653: 		jindex = 0;
654: 		goto fail_jinode_gh;
655: 	}
656: 
657: 	sdp->sd_jindex = gfs2_lookup_simple(master, "jindex");
658: 	if (IS_ERR(sdp->sd_jindex)) {
659: 		fs_err(sdp, "can't lookup journal index: %d\n", error);
660: 		return PTR_ERR(sdp->sd_jindex);
661: 	}
662: 
663: 	/* Load in the journal index special file */
664: 
665: 	error = gfs2_jindex_hold(sdp, &ji_gh);
666: 	if (error) {
667: 		fs_err(sdp, "can't read journal index: %d\n", error);
668: 		goto fail;
669: 	}
670: 
671: 	error = -EUSERS;
672: 	if (!gfs2_jindex_size(sdp)) {
673: 		fs_err(sdp, "no journals!\n");
674: 		goto fail_jindex;
675: 	}
676: 
677: 	atomic_set(&sdp->sd_log_blks_needed, 0);
678: 	if (sdp->sd_args.ar_spectator) {
679: 		sdp->sd_jdesc = gfs2_jdesc_find(sdp, 0);
680: 		atomic_set(&sdp->sd_log_blks_free, sdp->sd_jdesc->jd_blocks);
681: 		atomic_set(&sdp->sd_log_thresh1, 2*sdp->sd_jdesc->jd_blocks/5);
682: 		atomic_set(&sdp->sd_log_thresh2, 4*sdp->sd_jdesc->jd_blocks/5);
683: 	} else {
684: 		if (sdp->sd_lockstruct.ls_jid >= gfs2_jindex_size(sdp)) {
685: 			fs_err(sdp, "can't mount journal #%u\n",
686: 			       sdp->sd_lockstruct.ls_jid);
687: 			fs_err(sdp, "there are only %u journals (0 - %u)\n",
688: 			       gfs2_jindex_size(sdp),
689: 			       gfs2_jindex_size(sdp) - 1);
690: 			goto fail_jindex;
691: 		}
692: 		sdp->sd_jdesc = gfs2_jdesc_find(sdp, sdp->sd_lockstruct.ls_jid);
693: 
694: 		error = gfs2_glock_nq_num(sdp, sdp->sd_lockstruct.ls_jid,
695: 					  &gfs2_journal_glops,
696: 					  LM_ST_EXCLUSIVE, LM_FLAG_NOEXP,
697: 					  &sdp->sd_journal_gh);
698: 		if (error) {
699: 			fs_err(sdp, "can't acquire journal glock: %d\n", error);
700: 			goto fail_jindex;
701: 		}
702: 
703: 		ip = GFS2_I(sdp->sd_jdesc->jd_inode);
704: 		error = gfs2_glock_nq_init(ip->i_gl, LM_ST_SHARED,
705: 					   LM_FLAG_NOEXP | GL_EXACT | GL_NOCACHE,
706: 					   &sdp->sd_jinode_gh);
707: 		if (error) {
708: 			fs_err(sdp, "can't acquire journal inode glock: %d\n",
709: 			       error);
710: 			goto fail_journal_gh;
711: 		}
712: 
713: 		error = gfs2_jdesc_check(sdp->sd_jdesc);
714: 		if (error) {
715: 			fs_err(sdp, "my journal (%u) is bad: %d\n",
716: 			       sdp->sd_jdesc->jd_jid, error);
717: 			goto fail_jinode_gh;
718: 		}
719: 		atomic_set(&sdp->sd_log_blks_free, sdp->sd_jdesc->jd_blocks);
720: 		atomic_set(&sdp->sd_log_thresh1, 2*sdp->sd_jdesc->jd_blocks/5);
721: 		atomic_set(&sdp->sd_log_thresh2, 4*sdp->sd_jdesc->jd_blocks/5);
722: 
723: 		/* Map the extents for this journal's blocks */
724: 		gfs2_map_journal_extents(sdp, sdp->sd_jdesc);
725: 	}
726: 	trace_gfs2_log_blocks(sdp, atomic_read(&sdp->sd_log_blks_free));
727: 
728: 	if (sdp->sd_lockstruct.ls_first) {
729: 		unsigned int x;
730: 		for (x = 0; x < sdp->sd_journals; x++) {
731: 			struct gfs2_jdesc *jd = gfs2_jdesc_find(sdp, x);
732: 
733: 			if (sdp->sd_args.ar_spectator) {
734: 				error = check_journal_clean(sdp, jd);
735: 				if (error)
736: 					goto fail_jinode_gh;
737: 				continue;
738: 			}
739: 			error = gfs2_recover_journal(jd, true);
740: 			if (error) {
741: 				fs_err(sdp, "error recovering journal %u: %d\n",
742: 				       x, error);
743: 				goto fail_jinode_gh;
744: 			}
745: 		}
746: 
747: 		gfs2_others_may_mount(sdp);
748: 	} else if (!sdp->sd_args.ar_spectator) {
749: 		error = gfs2_recover_journal(sdp->sd_jdesc, true);
750: 		if (error) {
751: 			fs_err(sdp, "error recovering my journal: %d\n", error);
752: 			goto fail_jinode_gh;
753: 		}
754: 	}
755: 
756: 	sdp->sd_log_idle = 1;
757: 	set_bit(SDF_JOURNAL_CHECKED, &sdp->sd_flags);
758: 	gfs2_glock_dq_uninit(&ji_gh);
759: 	jindex = 0;
760: 	INIT_WORK(&sdp->sd_freeze_work, gfs2_freeze_func);
761: 	return 0;
762: 
763: fail_jinode_gh:
764: 	if (!sdp->sd_args.ar_spectator)
765: 		gfs2_glock_dq_uninit(&sdp->sd_jinode_gh);
766: fail_journal_gh:
767: 	if (!sdp->sd_args.ar_spectator)
768: 		gfs2_glock_dq_uninit(&sdp->sd_journal_gh);
769: fail_jindex:
770: 	gfs2_jindex_free(sdp);
771: 	if (jindex)
772: 		gfs2_glock_dq_uninit(&ji_gh);
773: fail:
774: 	iput(sdp->sd_jindex);
775: 	return error;
776: }
